-- Identity on PostgreSQL: companies, users, workspaces, memberships, roles,
-- departments, teams, and the E2EE key material that must stay transactional
-- with the user row.
--
-- Ids are 24-hex strings generated by the application (same shape as before)
-- so MongoDB documents that still reference users/workspaces by id keep
-- working during the migration. Rarely-queried, loosely-shaped data lives in
-- jsonb columns (profile, preferences, settings) rather than 60 nullable
-- columns; anything that is filtered, joined or counted has its own column.

-- ───────────────────────────── companies ─────────────────────────────
CREATE TABLE IF NOT EXISTS companies (
    id                    text PRIMARY KEY,
    name                  text NOT NULL,
    display_name          text,
    logo                  text,
    website               text,
    domain                text UNIQUE,
    domain_verified       boolean NOT NULL DEFAULT false,
    domain_verification   jsonb,                      -- { token, expires }
    verification_status   text NOT NULL DEFAULT 'pending',   -- pending | verified | rejected
    rejection_reason      text,
    is_setup_complete     boolean NOT NULL DEFAULT false,
    setup_step            integer NOT NULL DEFAULT 0,
    auto_join_by_domain   boolean NOT NULL DEFAULT false,
    allowed_emails        text[] NOT NULL DEFAULT '{}',
    invite_policy         jsonb NOT NULL DEFAULT '{}'::jsonb,
    default_workspace_id  text,
    plan                  text NOT NULL DEFAULT 'free',
    billing_email         text,
    is_active             boolean NOT NULL DEFAULT true,
    suspended_at          timestamptz,
    suspension_reason     text,
    settings              jsonb NOT NULL DEFAULT '{}'::jsonb,
    limits                jsonb NOT NULL DEFAULT '{}'::jsonb,      -- maxUsers, maxWorkspaces, ...
    documents             jsonb NOT NULL DEFAULT '[]'::jsonb,
    sso                   jsonb NOT NULL DEFAULT '{}'::jsonb,      -- enabled, provider, metadataUrl, domain, config
    security_settings     jsonb NOT NULL DEFAULT '{}'::jsonb,
    phone                 jsonb NOT NULL DEFAULT '{}'::jsonb,      -- ownerPhone, otp, otpExpiresAt, verified
    metadata              jsonb,
    created_at            timestamptz NOT NULL DEFAULT now(),
    updated_at            timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS companies_active ON companies (is_active);
CREATE INDEX IF NOT EXISTS companies_verification ON companies (verification_status, created_at DESC);

CREATE TABLE IF NOT EXISTS company_admins (
    company_id   text NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
    user_id      text NOT NULL,
    role         text NOT NULL DEFAULT 'admin',          -- owner | admin
    assigned_at  timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (company_id, user_id)
);

-- ─────────────────────────────── users ───────────────────────────────
CREATE TABLE IF NOT EXISTS users (
    id                        text PRIMARY KEY,
    username                  text NOT NULL,
    email                     text NOT NULL UNIQUE,
    personal_email            text,
    company_email             text,
    phone                     text UNIQUE,
    phone_code                text NOT NULL DEFAULT '+1',
    password_hash             text,
    user_type                 text NOT NULL DEFAULT 'individual',   -- individual | company
    company_id                text REFERENCES companies(id) ON DELETE SET NULL,
    company_role              text,                                  -- owner | admin | manager | member | guest
    co_owner_of               text,
    reports_to                text,
    job_title                 text,
    joining_date              timestamptz,
    employee_category         text,
    personal_workspace_id     text,
    roles                     text[] NOT NULL DEFAULT '{user}',      -- platform roles (user, platform-admin)
    verified                  boolean NOT NULL DEFAULT false,
    account_status            text NOT NULL DEFAULT 'active',        -- active | suspended | removed | blocked
    is_active                 boolean NOT NULL DEFAULT true,
    deactivated_at            timestamptz,
    suspension                jsonb,                                 -- { at, by, reason }
    auth_provider             text NOT NULL DEFAULT 'local',
    google_id                 text UNIQUE,
    github_id                 text UNIQUE,
    linkedin_id               text UNIQUE,
    sso                       jsonb,                                 -- { provider, id }
    password_flags            jsonb NOT NULL DEFAULT '{}'::jsonb,    -- setAt, loginEnabled, skipped, temporary, initialized
    two_factor_enabled        boolean NOT NULL DEFAULT false,
    two_factor_secret         text,
    failed_login_attempts     integer NOT NULL DEFAULT 0,
    locked_until              timestamptz,
    login_guard               jsonb NOT NULL DEFAULT '{}'::jsonb,    -- unverified attempts, last verification email
    tokens                    jsonb NOT NULL DEFAULT '{}'::jsonb,    -- invite / verification / reset token hashes + expiries
    profile_picture           text,
    profile_picture_path      text,
    profile                   jsonb NOT NULL DEFAULT '{}'::jsonb,
    preferences               jsonb NOT NULL DEFAULT '{}'::jsonb,
    permissions               jsonb NOT NULL DEFAULT '{}'::jsonb,
    roles_per_company         jsonb,
    encryption                jsonb,                                 -- legacy public/encrypted private key envelope
    social                    jsonb NOT NULL DEFAULT '{}'::jsonb,    -- favorites, blockedUsers, mutedChats
    device_tokens             jsonb NOT NULL DEFAULT '{}'::jsonb,
    legal_hold                jsonb,                                 -- { enabled, reason, setBy, at }
    retention_days            integer,
    last_login_method         text,
    last_login_method_at      timestamptz,
    last_login_at             timestamptz,
    last_activity_at          timestamptz NOT NULL DEFAULT now(),
    is_online                 boolean NOT NULL DEFAULT false,
    user_status               text NOT NULL DEFAULT 'active',
    work_history              jsonb NOT NULL DEFAULT '[]'::jsonb,
    created_at                timestamptz NOT NULL DEFAULT now(),
    updated_at                timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS users_company_status ON users (company_id, account_status);
CREATE INDEX IF NOT EXISTS users_username ON users (lower(username));
CREATE INDEX IF NOT EXISTS users_company_role ON users (company_id, company_role);

CREATE TABLE IF NOT EXISTS user_emails (
    id          text PRIMARY KEY,
    user_id     text NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    email       text NOT NULL,
    verified    boolean NOT NULL DEFAULT false,
    is_primary  boolean NOT NULL DEFAULT false,
    token_hash  text,
    token_expires timestamptz,
    added_at    timestamptz NOT NULL DEFAULT now(),
    UNIQUE (user_id, email)
);

CREATE TABLE IF NOT EXISTS user_refresh_tokens (
    token_hash   text PRIMARY KEY,
    user_id      text NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    expires_at   timestamptz NOT NULL,
    device_info  text,
    ip           text,
    started_at   timestamptz NOT NULL DEFAULT now(),
    created_at   timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS user_refresh_tokens_user ON user_refresh_tokens (user_id, expires_at);

CREATE TABLE IF NOT EXISTS user_otp_codes (
    id          bigserial PRIMARY KEY,
    user_id     text NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    code        text NOT NULL,
    type        text NOT NULL,                 -- reactivation | login | ...
    expires_at  timestamptz NOT NULL,
    used        boolean NOT NULL DEFAULT false,
    created_at  timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS user_otp_codes_user ON user_otp_codes (user_id, type, used);

CREATE TABLE IF NOT EXISTS user_devices (
    id          text PRIMARY KEY,
    user_id     text NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    name        text,
    platform    text,
    push_token  text,
    last_seen   timestamptz,
    meta        jsonb NOT NULL DEFAULT '{}'::jsonb,
    created_at  timestamptz NOT NULL DEFAULT now()
);

-- ───────────────────────────── workspaces ────────────────────────────
CREATE TABLE IF NOT EXISTS workspaces (
    id                text PRIMARY KEY,
    company_id        text REFERENCES companies(id) ON DELETE CASCADE,
    type              text NOT NULL DEFAULT 'team',    -- team | project | department | personal | company
    department_id     text,
    name              text NOT NULL,
    description       text NOT NULL DEFAULT '',
    icon              text NOT NULL DEFAULT '📁',
    color             text NOT NULL DEFAULT '#2563eb',
    rules             text NOT NULL DEFAULT '',
    created_by        text NOT NULL,
    default_channels  text[] NOT NULL DEFAULT '{}',
    settings          jsonb NOT NULL DEFAULT '{}'::jsonb,
    template_id       text,
    cloned_from       text,
    exported_at       timestamptz,
    analytics_cache   jsonb NOT NULL DEFAULT '{}'::jsonb,
    last_activity_at  timestamptz NOT NULL DEFAULT now(),
    is_active         boolean NOT NULL DEFAULT true,
    is_archived       boolean NOT NULL DEFAULT false,
    archived_at       timestamptz,
    metadata          jsonb,
    created_at        timestamptz NOT NULL DEFAULT now(),
    updated_at        timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS workspaces_company_name ON workspaces (company_id, name);
CREATE INDEX IF NOT EXISTS workspaces_company_created ON workspaces (company_id, created_at DESC);
CREATE INDEX IF NOT EXISTS workspaces_type_active ON workspaces (type, is_active);

CREATE TABLE IF NOT EXISTS workspace_members (
    workspace_id  text NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
    user_id       text NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    role          text NOT NULL DEFAULT 'member',       -- owner | admin | member
    status        text NOT NULL DEFAULT 'active',       -- active | suspended | removed
    joined_at     timestamptz NOT NULL DEFAULT now(),
    suspended_at  timestamptz,
    suspended_by  text,
    removed_at    timestamptz,
    removed_by    text,
    PRIMARY KEY (workspace_id, user_id)
);
CREATE INDEX IF NOT EXISTS workspace_members_user ON workspace_members (user_id, status);

CREATE TABLE IF NOT EXISTS workspace_permissions (
    workspace_id         text PRIMARY KEY REFERENCES workspaces(id) ON DELETE CASCADE,
    company_id           text,
    channel_permissions  jsonb NOT NULL DEFAULT '[]'::jsonb,
    feature_toggles      jsonb NOT NULL DEFAULT '{}'::jsonb,
    invite_permission    text NOT NULL DEFAULT 'admin',
    channel_creation     text NOT NULL DEFAULT 'member',
    updated_by           text,
    updated_at           timestamptz NOT NULL DEFAULT now()
);

-- ──────────────────────── departments and teams ──────────────────────
CREATE TABLE IF NOT EXISTS departments (
    id                    text PRIMARY KEY,
    company_id            text NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
    name                  text NOT NULL,
    description           text NOT NULL DEFAULT '',
    head_user_id          text,
    parent_department_id  text,
    default_workspace_id  text,
    workspaces            text[] NOT NULL DEFAULT '{}',
    metadata              jsonb,
    is_active             boolean NOT NULL DEFAULT true,
    created_at            timestamptz NOT NULL DEFAULT now(),
    updated_at            timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS departments_company_name ON departments (company_id, name);

CREATE TABLE IF NOT EXISTS department_members (
    department_id  text NOT NULL REFERENCES departments(id) ON DELETE CASCADE,
    user_id        text NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    role           text NOT NULL DEFAULT 'member',     -- manager | member
    PRIMARY KEY (department_id, user_id)
);
CREATE INDEX IF NOT EXISTS department_members_user ON department_members (user_id);

CREATE TABLE IF NOT EXISTS teams (
    id             text PRIMARY KEY,
    company_id     text NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
    department_id  text,
    workspace_id   text,
    name           text NOT NULL,
    description    text NOT NULL DEFAULT '',
    icon           text NOT NULL DEFAULT '👥',
    color          text NOT NULL DEFAULT '#6366f1',
    lead_user_id   text,
    is_active      boolean NOT NULL DEFAULT true,
    created_at     timestamptz NOT NULL DEFAULT now(),
    updated_at     timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS teams_company_active ON teams (company_id, is_active);

CREATE TABLE IF NOT EXISTS team_members (
    team_id    text NOT NULL REFERENCES teams(id) ON DELETE CASCADE,
    user_id    text NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    role       text NOT NULL DEFAULT 'member',         -- lead | member
    joined_at  timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (team_id, user_id)
);

-- Company-level role → permission matrix (models/Permission.js)
CREATE TABLE IF NOT EXISTS company_role_permissions (
    company_id          text NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
    role                text NOT NULL,
    permissions         jsonb NOT NULL DEFAULT '{}'::jsonb,
    custom_permissions  jsonb,
    updated_at          timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (company_id, role)
);

-- ───────────────────────────── E2EE keys ─────────────────────────────
CREATE TABLE IF NOT EXISTS user_identity_keys (
    user_id     text PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,
    public_key  text NOT NULL,
    algorithm   text NOT NULL,                       -- X25519 | RSA-2048
    version     integer NOT NULL DEFAULT 1,
    created_at  timestamptz NOT NULL DEFAULT now(),
    updated_at  timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS user_crypto_state (
    user_id                        text PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,
    identity_public_key            text,
    encrypted_identity_private_key text,
    identity_private_key_iv        text,
    umek_envelope                  text,
    umek_envelope_iv               text,
    umek_salt                      text,
    umek_protection_type           text,
    algorithm                      text,
    kek_version                    integer,
    version                        integer NOT NULL DEFAULT 1,
    created_at                     timestamptz NOT NULL DEFAULT now(),
    updated_at                     timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS conversation_keys (
    id                       text PRIMARY KEY,
    conversation_id          text NOT NULL,
    conversation_type        text NOT NULL,            -- channel | dm
    workspace_id             text NOT NULL,
    workspace_encrypted_key  jsonb,
    version                  integer NOT NULL DEFAULT 1,
    created_at               timestamptz NOT NULL DEFAULT now(),
    updated_at               timestamptz NOT NULL DEFAULT now(),
    UNIQUE (conversation_id, conversation_type)
);
CREATE INDEX IF NOT EXISTS conversation_keys_workspace ON conversation_keys (workspace_id);

CREATE TABLE IF NOT EXISTS conversation_key_members (
    conversation_key_id   text NOT NULL REFERENCES conversation_keys(id) ON DELETE CASCADE,
    user_id               text NOT NULL,
    encrypted_key         text NOT NULL,
    ephemeral_public_key  text,
    algorithm             text NOT NULL,
    added_at              timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (conversation_key_id, user_id)
);
CREATE INDEX IF NOT EXISTS conversation_key_members_user ON conversation_key_members (user_id);

-- ───────────────────────────── sessions ──────────────────────────────
CREATE TABLE IF NOT EXISTS user_sessions (
    id                text PRIMARY KEY,
    user_id           text NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    company_id        text,
    token_hash        text,
    device            text,
    os                text,
    browser           text,
    ip_address        text,
    location          text,
    last_activity_at  timestamptz NOT NULL DEFAULT now(),
    expires_at        timestamptz,
    is_active         boolean NOT NULL DEFAULT true,
    logout_at         timestamptz,
    created_at        timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS user_sessions_user ON user_sessions (user_id, is_active);

CREATE TABLE IF NOT EXISTS user_device_sessions (
    user_id           text NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    device_id         text NOT NULL,
    device_name       text,
    platform          text,
    revoked           boolean NOT NULL DEFAULT false,
    revoked_at        timestamptz,
    last_activity_at  timestamptz NOT NULL DEFAULT now(),
    meta              jsonb NOT NULL DEFAULT '{}'::jsonb,
    created_at        timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (user_id, device_id)
);

CREATE TABLE IF NOT EXISTS invites (
    id            text PRIMARY KEY,
    company_id    text,
    workspace_id  text,
    email         text NOT NULL,
    role          text,
    token_hash    text,
    invited_by    text,
    status        text NOT NULL DEFAULT 'pending',
    expires_at    timestamptz,
    accepted_at   timestamptz,
    meta          jsonb NOT NULL DEFAULT '{}'::jsonb,
    created_at    timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS invites_email ON invites (lower(email), status);
CREATE INDEX IF NOT EXISTS invites_company ON invites (company_id, status);
